import { t } from './i18n.js';
import { esc, money, metric, statusChip, modal, banner } from './components.js';

const userName = (state, id) => state.users.find((user) => user.id === id)?.name || '—';
const typeLabel = (type, locale) => ({ referral: t('referral', locale), uni: t('uni', locale), structure: locale === 'th' ? 'โครงสร้าง 3 ชั้น · 10 จ่ายทันที + 10 รีบอร์น' : 'Structure · 10 realtime + 10 rebirth', fvr: t('fvr', locale) }[type] || type);
function payoutPlan(locale) { return `<div class="panel payout-plan"><div class="panel-head"><div><span class="eyebrow">PAYOUT PLAN / 100 USDT</span><h3>${t('breakdown', locale)}</h3></div><span class="tiny-label">100%</span></div><div class="plan-flow"><span class="plan-source">PACKAGE<br><b>100 USDT</b></span><i></i><span class="plan-destination">WALLETS<br><b>4 ROUTES</b></span></div><div class="plan-rows"><div class="plan-row referral"><span class="plan-index">01</span><div><b>${t('referral', locale)}</b><small>ผู้แนะนำตรง / Referral wallet</small></div><strong>20 USDT</strong><em>20%</em></div><div class="plan-row uni"><span class="plan-index">02</span><div><b>Uni 10 ชั้น</b><small>สายเลือด · ชั้นละ 1 USDT</small></div><strong>10 USDT</strong><em>10%</em></div><div class="plan-row structure"><span class="plan-index">03</span><div><b>${t('structure', locale)}</b><small>Ternary Tree · 3 ชั้น · ชั้นละ 20 USDT · จ่ายทันที 10 + รีบอร์น 10</small></div><strong>60 USDT</strong><em>60%</em></div><div class="plan-row fvr"><span class="plan-index">04</span><div><b>FRM</b><small>System wallet · กระเป๋าระบบ</small></div><strong>10 USDT</strong><em>10%</em></div></div><div class="plan-total"><span>Total payout</span><b>100 USDT</b><em>100%</em></div></div>`; }

export function layout(state, active, content, handlers) {
  const locale = state.locale; const session = state.session;
  const nav = session ? `<nav>${[['dashboard','⌂'],['tree','⌘'],['transactions','⇄'],['earnings','◒'],...(session.role === 'admin' ? [['admin','▦']] : [])].map(([key, icon]) => `<button class="nav-item ${active === key ? 'active' : ''}" data-view="${key}"><i>${icon}</i>${t(key, locale)}</button>`).join('')}</nav>` : '';
  const chrome = active === 'tree' ? '' : `<header class="topbar"><div><span class="eyebrow">${active ? t(active, locale) : t('demo', locale)}</span><h1>${session ? `${t('overview', locale)} <em>/${session.username}</em>` : t('brand', locale)}</h1></div><div class="top-actions">${session ? `<span class="role-pill">${session.role === 'admin' ? 'ADMIN' : 'USER'}</span>` : ''}<span class="live-dot">● ${t('demo', locale)}</span></div></header>${banner(locale)}`;
  return `<div class="app-shell"><aside class="sidebar"><div class="brand-mark"><div class="orb">FM</div><div><b>${t('brand', locale)}</b><small>${t('tagline', locale)}</small></div></div>${nav}<div class="side-bottom"><button class="ghost" data-action="toggle-locale">${locale === 'th' ? 'EN' : 'TH'} <span>◐</span></button>${session ? `<button class="ghost" data-action="reset">↺ ${t('reset', locale)}</button>` : ''}</div></aside><main class="main">${chrome}${content}</main></div>`;
}

export function entry(state) { const l = state.locale; return layout(state, '', `<section class="hero"><div class="hero-copy"><span class="eyebrow">${t('demo', l)} · FM-001</span><h2>ดูระบบไตรนารี<br><span>แบบเข้าใจง่าย</span></h2><p>ทดลองซื้อแพ็กเกจจำลอง สร้างสายงาน และไล่ดูเส้นทางการจ่ายเงินแบบโปร่งใสในหน้าจอเดียว</p><div class="hero-actions"><button class="primary" data-action="demo-user">${t('userDemo', l)} <span>↗</span></button><button class="secondary" data-action="demo-admin">${t('adminDemo', l)}</button></div><p class="fineprint">${t('security', l)} · ${t('demoNote', l)}</p></div><div class="hero-visual"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="hero-card"><span>FRM</span><strong>100</strong><small>USDT simulated package</small><div class="split"><i></i><i></i><i></i><i></i></div><div class="split-labels"><span>20% Referral</span><span>60% Structure</span></div></div></div></section><section class="entry-grid"><div class="entry-card"><span class="card-kicker">01 / START</span><h3>${t('empty', l)}</h3><p>${t('emptyHint', l)}</p><button class="text-button" data-action="register">${t('register', l)} <span>→</span></button></div><div class="entry-card accent"><span class="card-kicker">02 / EXPLORE</span><h3>${t('flow', l)}</h3><p>ติดตามทุก USDT จากต้นทาง → กติกา → ผู้รับ → กระเป๋า</p><div class="mini-flow"><b>USER</b><span>→</span><b>RULE</b><span>→</span><b>WALLET</b></div></div></section>`, null); }

export function dashboard(state) { const l = state.locale; const payouts = state.payouts; const paid = payouts.filter((p) => p.status === 'paid').reduce((s, p) => s + p.amount, 0); const content = `<div class="page-grid"><section class="main-column"><div class="section-head"><div><span class="eyebrow">${t('dashboard', l)} / 01</span><h2>${state.users.length ? 'ระบบพร้อมทดลอง' : t('empty', l)}</h2></div>${state.session.role === 'user' ? `<button class="primary" data-action="buy">＋ ${t('buy', l)}</button>` : ''}</div><div class="metrics">${metric(t('members', l), state.users.length, 'cyan')}${metric(t('purchases', l), state.purchases.length)}${metric(t('paid', l), money(paid), 'green')}${metric(t('pending', l), payouts.filter((p) => p.status === 'pending').length, 'amber')}</div>${!state.users.length ? `<div class="empty-state"><div class="empty-icon">⌁</div><h3>${t('empty', l)}</h3><p>${t('emptyHint', l)}</p><button class="primary" data-action="register">${t('register', l)} →</button></div>` : `<div class="panel"><div class="panel-head"><h3>Recent activity</h3><button class="link-button" data-view="transactions">View all →</button></div>${recentRows(state, 5)}</div>`}</section><aside class="right-column">${payoutPlan(l)}<div class="panel note-panel"><span class="note-icon">!</span><div><b>${t('security', l)}</b><p>ยอดและการจ่ายทั้งหมดเป็นข้อมูลจำลอง</p></div></div></aside></div>`; return layout(state, 'dashboard', content); }

function recentRows(state, limit = 10) { const l = state.locale; const rows = state.payouts.slice(-limit).reverse(); if (!rows.length) return `<div class="table-empty">${t('noData', l)}</div>`; return `<div class="activity-list">${rows.map((p) => `<div class="activity-row"><div class="activity-icon ${p.type}">${p.type === 'fvr' ? 'F' : '↗'}</div><div class="activity-main"><b>${typeLabel(p.type, l)}</b><small>${userName(state, p.sourceUserId)} → ${esc(p.recipientName)}</small></div><strong>${money(p.amount)}</strong>${statusChip(p.status, l)}</div>`).join('')}</div>`; }

export function tree(state) { const l = state.locale; const root = state.binaryPositions.find((p) => !p.parentId); const rootUser = state.users.find((u) => u.id === root?.userId); const content = `<section class="tree-focus-page"><div class="tree-focus-actions"><button class="primary" data-action="register">＋ ${t('create', l)}</button></div>${rootUser ? treeGraph(state, rootUser.id, l) : `<div class="empty-state wide"><div class="empty-icon">⌘</div><h3>${t('empty', l)}</h3><p>${t('emptyHint', l)}</p><button class="primary" data-action="register">${t('create', l)} →</button></div>`}</section>`; return layout(state, 'tree', content); }

function treeGraph(state, rootId, locale) {
  const nodes = [];
  const edges = [];
  const slots = [];
  const MAX_TREE_DEPTH = 5;
  const slotIndex = { left: 0, center: 1, right: 2 };
  const normalizedSlot = (side) => side === 'right' ? 2 : side === 'center' ? 1 : 0;
  const walk = (userId, depth, path, parentId = null, side = null) => {
    const user = state.users.find((item) => item.id === userId);
    if (!user) return;
    if (depth > MAX_TREE_DEPTH) return;
    nodes.push({ user, depth, path, parentId, side });
    const children = state.binaryPositions.filter((item) => item.parentId === userId);
    for (const position of children) walk(position.userId, depth + 1, [...path, normalizedSlot(position.side)], userId, position.side);
    if (depth < MAX_TREE_DEPTH) {
      for (const sideName of ['left', 'center', 'right']) {
        if (!children.some((item) => normalizedSlot(item.side) === slotIndex[sideName])) slots.push({ parentId: userId, depth: depth + 1, path: [...path, slotIndex[sideName]], side: sideName });
      }
    }
  };
  walk(rootId, 0, [], null, null);
  const maxDepth = Math.max(0, ...nodes.map((node) => node.depth));
  const slot = 210;
  const width = Math.max(1200, 3 ** maxDepth * slot);
  const top = 72;
  const row = 260;
  const height = top + (maxDepth + 1) * row + 90;
  const point = (node) => {
    const scale = 3 ** node.depth;
    const index = node.path.reduce((value, part) => value * 3 + part, 0);
    return { x: ((index + 0.5) / scale) * width, y: top + node.depth * row };
  };
  nodes.forEach((node) => { if (node.parentId) edges.push({ from: nodes.find((item) => item.user.id === node.parentId), to: node }); });
  const lineMarkup = edges.map(({ from, to }) => { const directReferral = to.user.sponsorId === from.user.id; const a = point(from); const b = point(to); const structure = state.payouts.filter((payout) => payout.sourceUserId === to.user.id && payout.recipientUserId === from.user.id && payout.type === 'structure').reduce((sum, payout) => sum + payout.amount, 0); return `<line class="${directReferral ? 'direct-referral-line' : 'binary-placement-line indirect-referral-line'}" data-direct-referral="${directReferral ? 'true' : 'false'}" data-from="${from.user.id}" data-to="${to.user.id}" x1="${a.x}" y1="${a.y + 42}" x2="${b.x}" y2="${b.y - 42}" /><text x="${(a.x + b.x) / 2}" y="${(a.y + b.y) / 2 - 8}" class="edge-label">${structure ? `โครงสร้าง +${structure.toFixed(0)}` : 'Ternary placement'}</text>`; }).join('');
  const emptyLineMarkup = slots.map((slotNode) => { const parent = nodes.find((node) => node.user.id === slotNode.parentId); if (!parent) return ''; const a = point(parent); const b = point(slotNode); return `<line class="ternary-empty-line" data-empty-side="${slotNode.side}" data-from="${slotNode.parentId}" x1="${a.x}" y1="${a.y + 42}" x2="${b.x}" y2="${b.y - 20}" />`; }).join('');
  const slotMarkup = slots.map((slotNode) => { const { x, y } = point(slotNode); return `<div class="ternary-slot" data-parent="${slotNode.parentId}" data-side="${slotNode.side}" style="left:${x}px;top:${y - 20}px"><span>＋</span><small>${slotNode.side.toUpperCase()}</small></div>`; }).join('');
  const nodeMarkup = nodes.map((node) => { const { x, y } = point(node); const payouts = state.payouts.filter((payout) => payout.recipientUserId === node.user.id); const totalByType = (type) => payouts.filter((payout) => payout.type === type).reduce((sum, payout) => sum + payout.amount, 0); const hasPayout = payouts.length > 0; const initials = node.user.name.trim().slice(0, 2).toUpperCase(); const parent = node.parentId ? state.users.find((item) => item.id === node.parentId) : null; const sponsor = node.user.sponsorId ? state.users.find((item) => item.id === node.user.sponsorId) : null; const position = node.side ? node.side.toUpperCase() : 'ROOT'; return `<div class="graph-node ${node.depth === 0 ? 'root' : ''} ${node.user.isRebirth ? 'rebirth-node' : ''}" style="left:${x}px;top:${y - 42}px" data-user="${node.user.id}" data-sponsor="${node.user.sponsorId || ''}" data-side="${node.side || 'root'}"><div class="node-badge"><span class="node-status"></span><b>${esc(initials)}</b></div><div class="graph-meta"><b>${esc(node.user.name)}</b><small>L${node.depth} · ${esc(node.user.username)}</small><small class="relationship-meta">Sponsor: ${esc(sponsor?.name || 'System Root')}</small><small class="relationship-meta">Ternary Parent: ${esc(parent?.name || 'System Root')} · ${position}</small><em class="wallet-label">${esc(node.user.username)} wallet</em></div><div class="payment-chips ${hasPayout ? 'has-payout' : 'empty-payout'}"><span class="payment-chip referral">Referral <b>${totalByType('referral').toFixed(0)}</b></span><span class="payment-chip uni">Uni <b>${totalByType('uni').toFixed(0)}</b></span><span class="payment-chip structure">Tree <b>${totalByType('structure').toFixed(0)}</b></span></div></div>`; }).join('');
  return `<div class="tree-graph-shell"><div class="tree-graph-controls"><span class="zoom-label">TERNARY TREE · ZOOM <b data-zoom-value>100%</b></span><button class="secondary small" data-action="tree-zoom-out" aria-label="Zoom out">−</button><button class="secondary small" data-action="tree-zoom-in" aria-label="Zoom in">＋</button><button class="secondary small" data-action="tree-zoom-fit">Fit</button><button class="secondary small" data-action="tree-zoom-reset">Reset</button><button class="secondary small" data-action="tree-center" aria-label="Center tree">Center</button><span class="pan-hint">คลิก 1 ครั้ง: ไฮไลต์เส้นผู้แนะนำโดยตรง · ดับเบิ้ลคลิก: NODE INCOME DETAIL</span></div><div class="tree-canvas graph-canvas" data-tree-viewport><div class="binary-stage" data-tree-stage data-zoom="1" style="width:${width}px;height:${height}px"><svg class="binary-lines ternary-lines" viewBox="0 0 ${width} ${height}" aria-label="Ternary tree connections" role="img"><g>${lineMarkup}${emptyLineMarkup}</g></svg>${slotMarkup}${nodeMarkup}</div></div></div>`;
}

function treeNode(state, userId, depth) { const user = state.users.find((u) => u.id === userId); if (!user) return ''; const pos = state.binaryPositions.find((p) => p.userId === userId); const children = state.binaryPositions.filter((p) => p.parentId === userId); const income = state.payouts.filter((p) => p.recipientUserId === user.id).reduce((sum, payout) => sum + payout.amount, 0); const shortName = user.name.trim().slice(0, 2).toUpperCase(); const child = (side) => { const found = children.find((p) => p.side === side); return found ? treeNode(state, found.userId, depth + 1) : `<div class="tree-empty"><span>＋</span><small>ว่าง</small><em class="wallet-label">${esc(user.username)} wallet</em></div>`; }; return `<div class="tree-level"><div class="tree-node ${depth === 0 ? 'root' : ''}" data-user="${user.id}"><div class="node-badge"><span class="node-status"></span><b>${esc(shortName)}</b></div><div class="node-details"><b>${esc(user.name)}</b><small>@${esc(user.username)} · L${pos?.depth ?? 0}</small><strong>${state.purchases.filter((p) => p.buyerId === user.id).length} <i>buys</i></strong><em class="wallet-label">${esc(user.username)} wallet · ${income.toFixed(2)} USDT</em></div></div><div class="tree-line tree-line-vertical"></div><div class="tree-children"><div class="tree-line tree-line-horizontal"></div><div class="branch"><span class="branch-label">LEFT</span><span class="branch-flow">↙ structure wallet</span>${child('left')}</div><div class="branch"><span class="branch-label">RIGHT</span><span class="branch-flow">↘ structure wallet</span>${child('right')}</div></div></div>`; }

function legacyTransactions(state) { const l = state.locale; const content = `<section class="full-page"><div class="section-head"><div><span class="eyebrow">${t('transactions', l)} / AUDIT TRAIL</span><h2>${t('flow', l)}</h2><p class="subtext">คลิกธุรกรรมเพื่อดูเงิน 100 USDT ถูกแบ่งอย่างไร</p></div><div class="filter-pills"><button class="filter active">All</button><button class="filter">Pending</button></div></div><div class="panel transaction-panel"><div class="table-head"><span>Transaction / Source</span><span>${t('rule', l)}</span><span>${t('recipient', l)}</span><span>${t('amount', l)}</span><span>${t('status', l)}</span></div>${state.purchases.length ? state.purchases.slice().reverse().map((purchase) => `<div class="purchase-group"><div class="purchase-title"><b>◉ ${purchase.id}</b><span>${new Date(purchase.createdAt).toLocaleString(l === 'th' ? 'th-TH' : 'en-US')}</span><strong>${money(purchase.amount)}</strong><button class="text-button" data-action="show-flow" data-purchase="${purchase.id}">${t('flow', l)} →</button></div>${state.payouts.filter((p) => p.purchaseId === purchase.id).map((p) => `<div class="table-row"><span><b>${userName(state, p.sourceUserId)}</b><small>source user</small></span><span><span class="rule-tag ${p.type}">${typeLabel(p.type, l)}${p.level ? ` · L${p.level}` : ''}</span></span><span>${esc(p.recipientName)}<small>${esc(p.wallet)}</small></span><strong>${money(p.amount)}</strong>${statusChip(p.status, l)}</div>`).join('')}</div>`).join('') : `<div class="table-empty">${t('noData', l)}</div>`}</div></section>`; return layout(state, 'transactions', content); }

export function transactions(state) { const l = state.locale; const groups = state.purchases.slice().reverse().map((purchase) => { const payouts = state.payouts.filter((payout) => payout.purchaseId === purchase.id); const allocated = payouts.reduce((sum, payout) => sum + payout.amount, 0); return `<article class="transaction-flow"><div class="flow-header"><div><span class="eyebrow">PACKAGE PURCHASE</span><h3>${esc(userName(state, purchase.buyerId))} <small>· ${purchase.id}</small></h3><p>${new Date(purchase.createdAt).toLocaleString(l === 'th' ? 'th-TH' : 'en-US')}</p></div><div class="flow-amount"><b>${money(purchase.amount)}</b><span>ต้นทาง / Package</span></div><button class="text-button" data-action="show-flow" data-purchase="${purchase.id}">เปิดรายละเอียด →</button></div><div class="flow-source"><span class="flow-node-number">01</span><div><b>ต้นทาง: ${esc(userName(state, purchase.buyerId))}</b><small>ซื้อแพ็กเกจจำลอง 100 USDT</small></div><strong>${money(purchase.amount)}</strong></div><div class="flow-routes">${payouts.map((payout, index) => `<div class="flow-route"><span class="flow-node-number">${String(index + 2).padStart(2, '0')}</span><div><b><span class="rule-tag ${payout.type}">${typeLabel(payout.type, l)}${payout.level ? ` · L${payout.level}` : ''}</span> → ${esc(payout.recipientName)}</b><small>${esc(userName(state, payout.sourceUserId))} → ${esc(payout.wallet)}</small></div><strong>${money(payout.amount)}</strong><span>${statusChip(payout.status, l)}</span></div>`).join('')}</div><div class="flow-footer"><span>แบ่งจ่ายแล้ว ${payouts.length} รายการ</span><b>รวม ${money(allocated)} / 100 USDT</b></div></article>`; }).join(''); const content = `<section class="full-page"><div class="section-head"><div><span class="eyebrow">${t('transactions', l)} / AUDIT TRAIL</span><h2>Money Flow Explorer</h2><p class="subtext">ดูเงินจากต้นทางไปยังกติกา ผู้รับ และกระเป๋าในลำดับเดียวกัน</p></div><div class="filter-pills"><button class="filter active">ทั้งหมด</button><span class="flow-legend">ต้นทาง → การจ่าย → กระเป๋า</span></div></div><div class="transaction-list">${groups || `<div class="panel table-empty">${t('noData', l)}</div>`}</div></section>`; return layout(state, 'transactions', content); }

export function memberDetailsModal(state, userId) { const l = state.locale; const user = state.users.find((item) => item.id === userId); if (!user) return modal('member-details-modal', '<div class="modal"><button class="modal-close" data-action="close-modal">×</button><p>ไม่พบข้อมูลสมาชิก</p></div>'); const position = state.binaryPositions.find((item) => item.userId === user.id); const parent = state.users.find((item) => item.id === position?.parentId); const payouts = state.payouts.filter((payout) => payout.recipientUserId === user.id); const sumType = (type) => payouts.filter((payout) => payout.type === type).reduce((sum, payout) => sum + payout.amount, 0); const levelRows = (type) => { const levels = [...new Set(payouts.filter((payout) => payout.type === type).map((payout) => payout.level).filter(Boolean))].sort((a, b) => a - b); return levels.length ? levels.map((level) => `<div class="level-row"><span>Level ${level}</span><b>${money(payouts.filter((payout) => payout.type === type && payout.level === level).reduce((sum, payout) => sum + payout.amount, 0))}</b></div>`).join('') : '<div class="level-empty">ยังไม่มีรายได้ในส่วนนี้</div>'; }; return modal('member-details-modal', `<button class="modal-close" data-action="close-modal">×</button><span class="eyebrow">NODE INCOME DETAIL</span><h2>${esc(user.name)}</h2><div class="member-identity"><b>${esc(user.username)}</b><span>Sponsor: ${esc(userName(state, user.sponsorId))} · Ternary: ${position?.depth ?? '—'}${position?.side ? ` · ${position.side.toUpperCase()}` : ' · ROOT'}</span><small>Parent Node: ${esc(parent?.name || 'System Root')}</small></div><div class="income-grid"><div class="income-card referral"><span>Referral</span><b>${money(sumType('referral'))}</b></div><div class="income-card uni"><span>Uni</span><b>${money(sumType('uni'))}</b><div class="level-breakdown">${levelRows('uni')}</div></div><div class="income-card structure"><span>Structure</span><b>${money(sumType('structure'))}</b><div class="level-breakdown">${levelRows('structure')}</div></div><div class="income-card total"><span>รายได้รวม</span><b>${money(payouts.reduce((sum, payout) => sum + payout.amount, 0))}</b></div></div><div class="payout-detail"><div class="detail-head"><h3>รายการธุรกรรมที่เงินเข้ากระเป๋า</h3><span>${payouts.length} รายการ</span></div>${payouts.length ? payouts.slice().reverse().map((payout) => `<div class="payout-detail-row"><span class="rule-tag ${payout.type}">${typeLabel(payout.type, l)}${payout.level ? ` · L${payout.level}` : ''}</span><div><b>Source User: ${esc(userName(state, payout.sourceUserId))}</b><small>${typeLabel(payout.type, l)} → ${esc(payout.wallet)}</small></div><strong>${money(payout.amount)}</strong>${statusChip(payout.status, l)}</div>`).join('') : '<div class="level-empty">ยังไม่มีรายการรายได้เข้ากระเป๋า</div>'}</div>`); }

export function memberDetailsPanelModal(state, userId) {
  const l = state.locale; const user = state.users.find((item) => item.id === userId);
  if (!user) return modal('member-details-modal', '<button class="modal-close" data-action="close-modal">×</button><p>ไม่พบข้อมูลสมาชิก</p>');
  const position = state.binaryPositions.find((item) => item.userId === user.id); const parent = state.users.find((item) => item.id === position?.parentId);
  const payouts = state.payouts.filter((payout) => payout.recipientUserId === user.id); const sumType = (type, role = null) => payouts.filter((payout) => payout.type === type && (!role || payout.walletRole === role)).reduce((sum, payout) => sum + payout.amount, 0);
  const levelRows = (type, role = null) => { const levels = [...new Set(payouts.filter((payout) => payout.type === type && (!role || payout.walletRole === role)).map((payout) => payout.level).filter(Boolean))].sort((a, b) => a - b); return levels.length ? levels.map((level) => `<div class="level-row"><span>Level ${level}</span><b>${money(payouts.filter((payout) => payout.type === type && (!role || payout.walletRole === role) && payout.level === level).reduce((sum, payout) => sum + payout.amount, 0))}</b></div>`).join('') : '<div class="level-empty">ยังไม่มีรายได้ในส่วนนี้</div>'; };
  const payoutRows = [...new Map(payouts.map((payout) => [payout.purchaseId, payouts.filter((item) => item.purchaseId === payout.purchaseId)])).values()].reverse().map((batch, batchIndex) => { const batchTotal = batch.reduce((sum, payout) => sum + payout.amount, 0); const source = userName(state, batch[0]?.sourceUserId); return `<section class="payout-batch"><div class="payout-batch-head"><div><b>รอบที่ ${batchIndex + 1}</b><small>รายได้จาก Source User: ${esc(source)} · Package ${esc(batch[0]?.purchaseId || '—')}</small></div><strong>${money(batchTotal)}</strong></div><div class="payout-batch-rows">${batch.map((payout) => `<div class="payout-detail-row"><span class="rule-tag ${payout.type}">${typeLabel(payout.type, l)}${payout.level ? ` · L${payout.level}` : ''}</span><div><b>Source User: ${esc(userName(state, payout.sourceUserId))}</b><small>${typeLabel(payout.type, l)} → ${esc(payout.wallet)}</small></div><strong>${money(payout.amount)}</strong>${statusChip(payout.status, l)}</div>`).join('')}</div></section>`; }).join('') || '<div class="level-empty">ยังไม่มีรายการรายได้เข้ากระเป๋า</div>';
  return modal('member-details-modal', `<button class="modal-close" data-action="close-modal">×</button><div class="member-detail-layout"><section class="member-detail-summary"><span class="eyebrow">NODE INCOME DETAIL</span><h2>${esc(user.name)}</h2><div class="member-identity"><b>${esc(user.username)}</b><span>Sponsor: ${esc(userName(state, user.sponsorId))} · Ternary: ${position?.depth ?? '—'}${position?.side ? ` · ${position.side.toUpperCase()}` : ' · ROOT'}</span><small>Parent Node: ${esc(parent?.name || 'System Root')}</small></div>${rebirthRegistry(state, user.id)}<div class="income-grid"><div class="income-card referral"><span>Referral</span><b>${money(sumType('referral'))}</b></div><div class="income-card uni"><span>Uni</span><b>${money(sumType('uni'))}</b><div class="level-breakdown">${levelRows('uni')}</div></div><div class="income-card structure-summary structure-full-width"><div class="structure-summary-head"><div><span>Structure · รวม 3 ชั้น</span><small class="structure-formula">Ternary Tree · 3 ชั้น · ชั้นละ 20 USDT</small></div><b>${money(sumType('structure'))}</b></div><div class="structure-split"><div class="structure-realtime"><span>Real Time</span><b>${money(sumType('structure', 'realtime'))}</b><div class="level-breakdown">${levelRows('structure', 'realtime')}</div></div><div class="structure-reserve"><span>สะสม</span><b>${money(sumType('structure', 'reserve'))}</b><div class="level-breakdown">${levelRows('structure', 'reserve')}</div></div></div></div><div class="income-card total"><span>รายได้รวม</span><b>${money(payouts.reduce((sum, payout) => sum + payout.amount, 0))}</b></div></div></section><aside class="payout-detail payout-detail-side"><div class="detail-head"><h3>รายการธุรกรรมที่เงินเข้ากระเป๋า</h3><span>${payouts.length} รายการ · แยกตามรอบ</span></div>${payoutRows}</aside></div>`);
}

export function flowModal(state, purchaseId) { const l = state.locale; const purchase = state.purchases.find((p) => p.id === purchaseId); const payouts = state.payouts.filter((p) => p.purchaseId === purchaseId); return modal('flow-modal', `<button class="modal-close" data-action="close-modal">×</button><span class="eyebrow">TRANSACTION TRACE</span><h2>${t('flow', l)}</h2><p class="subtext">${purchase?.id} · ${money(purchase?.amount)}</p><div class="flow-steps"><div class="flow-step"><i class="flow-num">01</i><div><b>${userName(state, purchase?.buyerId)}</b><small>Source user · package purchase</small></div><strong>100 USDT</strong></div>${payouts.slice(0, 8).map((p, index) => `<div class="flow-step"><i class="flow-num">${String(index + 2).padStart(2, '0')}</i><div><b>${typeLabel(p.type, l)}${p.level ? ` · Level ${p.level}` : ''}</b><small>${userName(state, p.sourceUserId)} → ${esc(p.recipientName)}</small></div><strong>${money(p.amount)}</strong></div>`).join('')}</div><div class="flow-total"><span>Total allocated</span><b>${money(payouts.reduce((s, p) => s + p.amount, 0))}</b></div>`); }

export function transactionsAudit(state) { const l = state.locale; const groups = state.purchases.slice().reverse().map((purchase) => { const payouts = state.payouts.filter((payout) => payout.purchaseId === purchase.id); const sumType = (type) => payouts.filter((payout) => payout.type === type).reduce((sum, payout) => sum + payout.amount, 0); const total = payouts.reduce((sum, payout) => sum + payout.amount, 0); const split = ['referral', 'uni', 'structure', 'fvr'].map((type) => `<span class="flow-split-chip ${type}"><small>${typeLabel(type, l)}</small><b>${money(sumType(type))}</b></span>`).join(''); return `<article class="transaction-flow"><div class="flow-header"><div><span class="eyebrow">PACKAGE PURCHASE</span><h3>${esc(userName(state, purchase.buyerId))} <small>· ${purchase.id}</small></h3><p>${new Date(purchase.createdAt).toLocaleString(l === 'th' ? 'th-TH' : 'en-US')}</p></div><div class="flow-amount"><b>${money(purchase.amount)}</b><span>ต้นทาง / Package</span></div><button class="text-button" data-action="show-flow" data-purchase="${purchase.id}">เปิดรายละเอียด →</button></div><div class="flow-split">${split}</div><div class="flow-source"><span class="flow-node-number">01</span><div><b>ต้นทาง: ${esc(userName(state, purchase.buyerId))}</b><small>ซื้อแพ็กเกจจำลอง ${money(purchase.amount)}</small></div><strong>${money(purchase.amount)}</strong></div><div class="flow-routes">${payouts.map((payout, index) => `<div class="flow-route"><span class="flow-node-number">${String(index + 2).padStart(2, '0')}</span><div><b><span class="rule-tag ${payout.type}">${typeLabel(payout.type, l)}${payout.level ? ` · L${payout.level}` : ''}</span> → ${esc(payout.recipientName)}</b><small>Source: ${esc(userName(state, payout.sourceUserId))} → Wallet: ${esc(payout.wallet)}</small></div><strong>${money(payout.amount)}</strong><span>${statusChip(payout.status, l)}</span></div>`).join('')}</div><div class="flow-footer"><span>${payouts.length} payout rows · ${payouts.filter((payout) => payout.status === 'unmatched').length} unmatched</span><b>รวม ${money(total)} / ${money(purchase.amount)}</b></div></article>`; }).join(''); const content = `<section class="full-page"><div class="section-head"><div><span class="eyebrow">${t('transactions', l)} / AUDIT TRAIL</span><h2>Money Flow Explorer</h2><p class="subtext">ตรวจสอบทุกยอดจาก Package → กติกา → ผู้รับ → Wallet โดยไม่รวมยอดข้ามรายการซื้อ</p></div><div class="filter-pills"><button class="filter active">ทั้งหมด</button><span class="flow-legend">ต้นทาง → การจ่าย → กระเป๋า</span></div></div><div class="transaction-list">${groups || `<div class="panel table-empty">${t('noData', l)}</div>`}</div></section>`; return layout(state, 'transactions', content); }

export function earningsDetailed(state) { const l = state.locale; const rows = state.users.map((user) => { const own = state.payouts.filter((payout) => payout.recipientUserId === user.id); const amount = (type, role = null) => own.filter((payout) => payout.type === type && (!role || payout.walletRole === role)).reduce((sum, payout) => sum + payout.amount, 0); const levels = (type, role = null) => { const grouped = new Map(); own.filter((payout) => payout.type === type && (!role || payout.walletRole === role) && payout.level).forEach((payout) => grouped.set(payout.level, (grouped.get(payout.level) || 0) + payout.amount)); return [...grouped.entries()].sort((a, b) => a[0] - b[0]).map(([level, total]) => `<span>L${level} ${money(total)}</span>`).join('') || '<span>ยังไม่มีรายการ</span>'; }; const position = state.binaryPositions.find((item) => item.userId === user.id); const total = own.reduce((sum, payout) => sum + payout.amount, 0); return `<article class="earn-user-card"><div class="earn-user-head"><div class="earn-user-identity"><div class="avatar">${esc(user.name.slice(0, 1))}</div><div><b>${esc(user.name)}</b><small>@${esc(user.username)}</small><small>Sponsor: ${esc(userName(state, user.sponsorId))} · Binary L${position?.depth ?? '—'}${position?.side ? ` · ${position.side.toUpperCase()}` : ''}</small></div></div><div class="earn-user-total"><small>รายได้รวม</small><b>${money(total)}</b><span>${own.length} payout rows · ${state.purchases.filter((purchase) => purchase.buyerId === user.id).length} purchases</span></div></div><div class="earn-wallet-grid"><div class="earn-wallet referral"><span>ค่าแนะนำ / Referral</span><b>${money(amount('referral'))}</b></div><div class="earn-wallet uni"><span>Uni 10 ชั้น</span><b>${money(amount('uni'))}</b><div>${levels('uni')}</div></div><div class="earn-wallet structure-summary"><div class="structure-summary-head"><span>Structure · รวม 3 ชั้น</span><b>${money(amount('structure'))}</b></div><div class="structure-split"><div class="structure-realtime"><span>Real Time</span><b>${money(amount('structure', 'realtime'))}</b><div>${levels('structure', 'realtime')}</div></div><div class="structure-reserve"><span>สะสม</span><b>${money(amount('structure', 'reserve'))}</b><div>${levels('structure', 'reserve')}</div></div></div></div><div class="earn-wallet fvr"><span>FRM Wallet</span><b>${money(amount('fvr'))}</b></div></div><button class="text-button earn-detail-button" data-action="member-details" data-user="${user.id}">ดูรายการที่มาของรายได้ทั้งหมด →</button></article>`; }).join(''); return layout(state, 'earnings', `<section class="full-page"><div class="section-head"><div><span class="eyebrow">${t('earnings', l)} / PER USER</span><h2>รายได้แยกตามกระเป๋า</h2><p class="subtext">ข้อมูลรวมทุก User, ทุกกระเป๋า, ทุก Level และจำนวนรายการจ่าย</p></div></div>${rebirthSearchPanel(state)}<div class="earnings-user-list">${rows || `<div class="panel table-empty">${t('noData', l)}</div>`}</div></section>`); }

export function earnings(state) { return earningsDetailed(state); }

export function admin(state) { const l = state.locale; return layout(state, 'admin', `<section class="full-page"><div class="section-head"><div><span class="eyebrow">ADMIN / CONTROL ROOM</span><h2>จัดการระบบจำลอง</h2><p class="subtext">ตรวจสอบสมาชิก ธุรกรรม และรอบจ่ายจากจุดเดียว</p></div><div class="admin-actions"><button class="secondary" data-action="seed-random-5">＋ จำลอง Random 5 ชั้น</button><button class="secondary" data-action="seed-random">＋ เพิ่ม Random 19 User</button><button class="primary" data-action="process">⚡ ${t('process', l)}</button></div></div><div class="metrics">${metric(t('members', l), state.users.length, 'cyan')}${metric(t('purchases', l), state.purchases.length)}${metric('Payout rows', state.payouts.length)}${metric('Unmatched', state.payouts.filter((p) => p.status === 'unmatched').length, 'amber')}</div><div class="panel"><div class="panel-head"><h3>Member registry</h3><span class="tiny-label">${state.users.length} records</span></div><div class="member-list">${state.users.map((u) => `<div class="member-row"><div class="avatar">${u.name.slice(0, 1)}</div><div><b>${esc(u.name)}</b><small>@${esc(u.username)} · sponsor ${userName(state, u.sponsorId)}</small></div><span>${state.purchases.filter((p) => p.buyerId === u.id).length} purchases</span><span class="chip success">active</span></div>`).join('') || `<div class="table-empty">${t('noData', l)}</div>`}</div></div></section>`); }
function rebirthRegistry(state, userId) {
  const records = (state.rebirths || []).filter((rebirth) => rebirth.ownerUserId === userId).map((rebirth) => {
    const code = state.users.find((user) => user.id === rebirth.userId);
    const position = state.binaryPositions.find((item) => item.userId === rebirth.userId);
    const parent = state.users.find((user) => user.id === position?.parentId);
    return `<button type="button" class="rebirth-row" data-action="focus-rebirth" data-user="${esc(rebirth.userId)}"><div><b>${esc(code?.name || rebirth.userId)}</b><small>${esc(code?.username || '—')} · ใต้ ${esc(parent?.name || 'System Root')} · ${position?.side ? position.side.toUpperCase() : 'ROOT'}</small></div><strong>${money(rebirth.amount)} <span>สร้างแล้ว</span></strong></button>`;
  });
  const reserve = state.reserveBalances?.[userId] || 0;
  return `<div class="rebirth-registry"><div class="rebirth-registry-head"><div><span class="eyebrow">REBIRTH REGISTRY</span><b>จุดเกิดใหม่</b></div><strong>${records.length} รหัส</strong></div><div class="rebirth-balance">ยอดสะสมปัจจุบัน <b>${money(reserve)}</b> / 100 USDT</div>${records.join('') || '<div class="level-empty">ยังไม่เกิด Rebirth Code</div>'}</div>`;
}

function rebirthSearchPanel(state) {
  const rows = (state.rebirths || []).map((rebirth) => {
    const owner = state.users.find((user) => user.id === rebirth.ownerUserId);
    const code = state.users.find((user) => user.id === rebirth.userId);
    const position = state.binaryPositions.find((item) => item.userId === rebirth.userId);
    const parent = state.users.find((user) => user.id === position?.parentId);
    const search = `${owner?.name || ''} ${owner?.username || ''} ${code?.name || ''} ${code?.username || ''}`.toLowerCase();
    return `<button type="button" class="rebirth-search-row" data-rebirth-entry data-search-text="${esc(search)}" data-action="focus-rebirth" data-user="${esc(rebirth.userId)}"><div><b>${esc(code?.name || rebirth.userId)}</b><small>เจ้าของ: ${esc(owner?.name || rebirth.ownerUserId)} · ใต้ ${esc(parent?.name || 'System Root')} · ${position?.side ? position.side.toUpperCase() : 'ROOT'}</small></div><strong>${money(rebirth.amount)}</strong></button>`;
  }).join('');
  return `<section class="rebirth-search"><div class="rebirth-search-head"><div><span class="eyebrow">REBIRTH SEARCH</span><h3>ค้นหาจุดเกิดใหม่</h3></div><span>${(state.rebirths || []).length} รหัส</span></div><input data-rebirth-search placeholder="ค้นหา User หรือ Rebirth Code..."><div class="rebirth-search-list">${rows || '<div class="level-empty">ยังไม่มี Rebirth Code</div>'}</div></section>`;
}
